-- Ejercicios que faltaban para las rutinas sueltas que pidió Manu (2026-11-27):
-- tracción, empuje, abdominales y estiramientos. Videos probados con revisar-videos.yml.
insert into public.exercises (name, category, muscle_groups, equipment, unilateral, instructions, coaching_cues, video_url)
select v.* from (values
('Remo con barra','fuerza',array['Dorsales','Espalda alta','Bíceps']::text[],array['Barra y discos']::text[],false,'De pie con la barra en las manos, inclinate hacia adelante desde la cadera con las rodillas apenas flexionadas. Llevá la barra hacia el ombligo juntando los omóplatos y bajala controlado.','Espalda neutra todo el tiempo. Codos cerca del cuerpo. No tirones con la cintura.','https://www.youtube.com/watch?v=5Gg2OPlCkuE'),
('Curl martillo','fuerza',array['Bíceps','Antebrazos']::text[],array['Mancuernas']::text[],false,'De pie con una mancuerna en cada mano y las palmas mirándose, flexioná los codos subiendo las mancuernas sin girar las muñecas. Bajá lento.','Codos pegados al cuerpo. Sin balancear el torso. Bajada controlada.','https://www.youtube.com/watch?v=RHdacbwKbTo'),
('Vuelos laterales','fuerza',array['Hombros']::text[],array['Mancuernas']::text[],false,'De pie con una mancuerna en cada mano, elevá los brazos hacia los costados con los codos apenas flexionados hasta la altura de los hombros. Bajá lento.','No subas los hombros a las orejas. Sin impulso. Peso liviano y buena técnica.','https://www.youtube.com/watch?v=qiX0Sv_yj-U'),
('Abdominales cortos (crunch)','core',array['Abdominales']::text[],array['Solo peso corporal']::text[],false,'Boca arriba con las rodillas flexionadas y los pies apoyados, despegá los hombros del piso acercando las costillas a la cadera. Bajá controlado.','Mirada al techo, sin tirar del cuello. Soltá el aire al subir. Recorrido corto.','https://www.youtube.com/watch?v=hl9Yu7UZqHU'),
('Estiramiento de isquiotibiales con banda','movilidad',array['Isquiotibiales']::text[],array['Bandas elásticas','Solo peso corporal']::text[],true,'Boca arriba, pasá una banda o toalla por la planta del pie y subí la pierna estirada hasta sentir el estiramiento atrás del muslo. Sostené.','Rodilla estirada. La otra pierna apoyada en el piso. Respirá lento.','https://www.youtube.com/watch?v=W538T-Sa6pU'),
('Estiramiento de cuádriceps de pie','movilidad',array['Cuádriceps','Flexores de cadera']::text[],array['Solo peso corporal']::text[],true,'De pie, tomá el empeine y llevá el talón hacia el glúteo con las rodillas juntas. Sostené y cambiá de pierna.','Cadera adelante, sin arquear la espalda. Apoyate en una pared si hace falta.','https://www.youtube.com/watch?v=uhP7-OCYQKk'),
('Estiramiento de glúteo (figura 4)','movilidad',array['Glúteos','Cadera']::text[],array['Solo peso corporal']::text[],true,'Boca arriba, cruzá un tobillo sobre la rodilla contraria y llevá las dos piernas hacia el pecho tomando el muslo de abajo. Sostené y cambiá.','Cabeza y hombros apoyados. Rodilla cruzada hacia afuera. Respirá.','https://www.youtube.com/watch?v=VgjgTGnBkx0'),
('Estiramiento de aductores (mariposa)','movilidad',array['Aductores','Cadera']::text[],array['Solo peso corporal']::text[],false,'Sentado, juntá las plantas de los pies y dejá caer las rodillas hacia los costados. Inclinate un poco hacia adelante con la espalda larga.','Espalda recta. No empujes las rodillas con fuerza. Respirá lento.','https://www.youtube.com/watch?v=NatR1CMhbRU'),
('Estiramiento de pecho en pared','movilidad',array['Pectorales','Hombros']::text[],array['Solo peso corporal']::text[],true,'Apoyá la mano y el antebrazo en una pared o marco de puerta a la altura del hombro y girá el cuerpo hacia el otro lado hasta sentir el pecho. Sostené y cambiá.','Hombro lejos de la oreja. Giro suave. Sin dolor en el hombro.','https://www.youtube.com/watch?v=ZXgkMIvXJ3E'),
('Estiramiento de hombro posterior','movilidad',array['Hombros','Espalda alta']::text[],array['Solo peso corporal']::text[],true,'Cruzá un brazo estirado por delante del pecho y acercalo con la otra mano tomándolo por encima del codo. Sostené y cambiá.','Hombro bajo. Torso quieto, sin girar. Respirá.','https://www.youtube.com/watch?v=3mcva7Qn-hc'),
('Estiramiento de gemelos en pared','movilidad',array['Pantorrillas']::text[],array['Solo peso corporal']::text[],true,'Con las manos en la pared, llevá una pierna atrás con el talón apoyado y la rodilla estirada, y llevá la cadera hacia la pared. Sostené y cambiá.','Talón de atrás en el piso. Pie apuntando hacia la pared. Sin rebotes.','https://www.youtube.com/watch?v=1-uPT7huss0'),
('Postura del niño','movilidad',array['Espalda baja','Dorsales','Cadera']::text[],array['Solo peso corporal']::text[],false,'De rodillas, sentate sobre los talones y llevá el pecho hacia el piso con los brazos estirados adelante. Sostené respirando.','Frente apoyada. Brazos largos. Soltá la espalda con cada exhalación.','https://www.youtube.com/watch?v=PC1IkjO1k5Q')
) as v(name, category, muscle_groups, equipment, unilateral, instructions, coaching_cues, video_url)
where not exists (select 1 from public.exercises e where e.org_id is null and lower(e.name) = lower(v.name));
